/**
 * How to draw a query result. This mirrors the `viz` part of a chart spec
 * (.agents/design/chart-dashboard.md): our own declarative description, with
 * nothing specific to a rendering library, because it is what gets stored,
 * versioned and generated by AI.
 */
import type { DisplayFormat } from './format'
import type { Hue, PaletteName } from './palette'

export type VizType = 'bar' | 'hbar' | 'line' | 'area' | 'combo' | 'scatter' | 'pie' | 'funnel' | 'treemap' | 'heatmap' | 'gauge' | 'kpi' | 'table' | 'pivot' | 'sankey'

export interface Axis {
  title?: string
  /** The ends of a value axis, which otherwise follow the data. */
  min?: number
  max?: number
  /** Turns a category axis's labels. */
  rotate?: 45 | 90
  /** Leaves out a value axis's grid lines. */
  hideGrid?: boolean
  hideLabels?: boolean
}

export type LegendPosition = 'top' | 'bottom' | 'left' | 'right' | 'none'
export type LabelContent = 'value' | 'percent' | 'none'

/** The look of a chart; absent means the default. Settings apply only to some types (see styleApplies). */
export interface Style {
  legend?: LegendPosition
  labels?: LabelContent
  palette?: PaletteName
  /** A hue of the palette for a measure, by its column. */
  colors?: Record<string, Hue>
  smooth?: boolean
  points?: boolean
  /** Stacks each category to the whole. */
  percent?: boolean
  /** A pie without the hole in the middle. */
  solid?: boolean
  /** The widest a bar is drawn, in pixels. */
  barWidth?: number
  /** Axes by where they are on screen; y2Axis is a combo chart's right axis. */
  xAxis?: Axis
  yAxis?: Axis
  y2Axis?: Axis
  /** The scale of a gauge without a target measure. */
  gauge?: { min?: number; max?: number }
  /** Where a sankey diagram's paths that end early stop: at the left or the right; at the last level without it. */
  nodeAlign?: 'left' | 'right'
  /** A table's rows alternate in shade. */
  striped?: boolean
  density?: 'compact' | 'comfortable'
  /** Keeps a table's first column in view while the rest scroll across. */
  freeze?: boolean
  /** Writes a run of equal values in a table's dimension columns once, within the runs of those to its left. */
  merge?: boolean
  /** Shows a table's rows a page at a time: pages of pageSize rows, or as many as fit. Every row without it. */
  paging?: 'pages' | 'auto'
  /** How many rows a page holds when paging is pages; 20 without it. */
  pageSize?: number
  /** Columns' widths in pixels, by output column. */
  widths?: Record<string, number>
  /** How a column's cells line up, by output column; numbers right and the rest left without it. */
  columnAlign?: Record<string, 'left' | 'center' | 'right'>
  /** A number's cell shaded by the first of its column's rules the value meets, by output column. */
  highlights?: Record<string, Highlight[]>
  /** Where a KPI's tiles stand, and how large. */
  textAlign?: 'left' | 'center'
  size?: 'small' | 'large'
  /** How a KPI's comparison is written: a percent change unless said otherwise. */
  compareAs?: 'percent' | 'diff' | 'both'
  /** A rise in red and a fall in green, as markets in China show them. */
  redUp?: boolean
}

/** The comparisons of a conditional format's rule, written as a query's filters write them. */
export const highlightOps = ['lt', 'lte', 'gt', 'gte', 'eq', 'ne'] as const
export type HighlightOp = (typeof highlightOps)[number]
export const highlightIcons = ['up', 'down', 'dot'] as const
export type HighlightIcon = (typeof highlightIcons)[number]

/**
 * A rule of a column's conditional format: a value that compares with value by
 * op has its cell shaded in the hue, with the icon before the number. The
 * value is the number as the query returns it, not as it is written.
 */
export interface Highlight {
  op: HighlightOp
  value: number
  color: Hue
  icon?: HighlightIcon
}

/** The most rules a column's conditional format has. */
export const maxHighlights = 5

/** A header over adjacent columns of a table: output columns by alias, or smaller groups, in the order the columns come. */
export interface ColumnGroup {
  label: string
  columns: (string | ColumnGroup)[]
}

export interface Viz {
  type: VizType
  /** Table output columns kept in the query but omitted from the presentation. */
  hiddenColumns?: string[]
  /** Headers over a table's adjacent columns, nested at most three deep. */
  columnGroups?: ColumnGroup[]
  /** Category column: along the axis, or naming a slice, stage, point or tile. */
  x?: string
  /** Measure columns. Apart from a combo chart's right axis they share one value axis. */
  y?: string[]
  /** Dimension column whose values become separate series, each with its colour. */
  series?: string
  /** A heatmap's or a pivot table's dimensions down the side and across the top. */
  rows?: string[]
  columns?: string[]
  /** A sankey diagram's dimensions, left to right; the measure flows from each level to the next. */
  levels?: string[]
  /** A KPI tile's measure, and the measure it is compared against, which is then not a tile. */
  compare?: Record<string, string>
  /** A combo chart's measures drawn as lines; the others are bars. */
  lines?: string[]
  /** A combo chart's measures read against the right axis. */
  rightAxis?: string[]
  stacked?: boolean
  /** Formats by output column, each replacing the dataset's format for that column whole. */
  formats?: Record<string, DisplayFormat>
  style?: Style
}

export const vizTypes: VizType[] = ['bar', 'hbar', 'line', 'area', 'combo', 'scatter', 'pie', 'funnel', 'treemap', 'heatmap', 'gauge', 'kpi', 'table', 'pivot', 'sankey']

/** What kind each axis of a type is, by where it is on screen; undefined where it has none. */
export function axisKinds(type: VizType): { xAxis?: 'value' | 'category'; yAxis?: 'value' | 'category'; y2Axis?: 'value' } {
  switch (type) {
    case 'bar':
    case 'line':
    case 'area':
      return { xAxis: 'category', yAxis: 'value' }
    case 'combo':
      return { xAxis: 'category', yAxis: 'value', y2Axis: 'value' }
    case 'hbar':
      return { xAxis: 'value', yAxis: 'category' }
    case 'scatter':
      return { xAxis: 'value', yAxis: 'value' }
    case 'heatmap':
      return { xAxis: 'category', yAxis: 'category' }
    default:
      return {}
  }
}

const cartesian: VizType[] = ['bar', 'hbar', 'line', 'area', 'combo']

/**
 * The chart types each style setting applies to; the server refuses it on
 * any other (internal/content/viz.go). Axes are told by axisKinds.
 */
export const styleApplies: Record<Exclude<keyof Style, 'xAxis' | 'yAxis' | 'y2Axis'>, VizType[]> = {
  legend: [...cartesian, 'scatter', 'pie', 'funnel', 'treemap'],
  labels: [...cartesian, 'scatter', 'pie', 'funnel', 'treemap', 'heatmap', 'sankey'],
  palette: [...cartesian, 'scatter', 'pie', 'treemap', 'sankey'],
  colors: cartesian,
  smooth: ['line', 'area', 'combo'],
  points: ['line', 'area', 'combo'],
  percent: ['bar', 'hbar', 'area'],
  solid: ['pie'],
  barWidth: ['bar', 'hbar', 'combo'],
  gauge: ['gauge'],
  nodeAlign: ['sankey'],
  striped: ['table', 'pivot'],
  density: ['table', 'pivot'],
  freeze: ['table', 'pivot'],
  // A pivot table merges its row dimensions always.
  merge: ['table'],
  // A pivot table's groups and subtotals would be cut across pages.
  paging: ['table'],
  pageSize: ['table'],
  widths: ['table', 'pivot'],
  columnAlign: ['table', 'pivot'],
  highlights: ['table', 'pivot'],
  textAlign: ['kpi'],
  size: ['kpi'],
  compareAs: ['kpi'],
  redUp: ['kpi'],
}

/** Types whose labels can be a share of the whole. */
export const shareTypes: VizType[] = ['pie', 'funnel', 'treemap', 'sankey']

/** Codes, not messages: the caller translates them. */
export type ChartErrorCode = 'unknown_column' | 'no_series' | 'non_numeric_series' | 'no_visible_columns'

export class ChartSpecError extends Error {
  constructor(
    readonly code: ChartErrorCode,
    readonly column?: string,
  ) {
    super(column ? `${code}: ${column}` : code)
    this.name = 'ChartSpecError'
  }
}
